<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { Search, Upload, Tags, SlidersHorizontal, ArrowUpRight, UserRoundCheck, FileText, Send } from '@/views/enterprise/components/icons'
import MiniAvatar from '@/views/enterprise/components/MiniAvatar.vue'
import ToastMessage from '@/views/enterprise/components/ToastMessage.vue'
import { api, reserveApi } from '@/views/enterprise/api/contract'

const router = useRouter(); const toast = ref(''); const keyword = ref(''); const status = ref('全部状态'); const selected = ref([])
const candidates = ref([
  { id: 8001, name: '李强', position: '高级前端工程师', status: '面试中', statusKey: 'interviewing', score: 92, stage: '专业技术面', updated: '今天 09:12', tags: ['高潜候选人', '技术深度'], color: '#635bff', focus: '需核实大型项目中的个人贡献' },
  { id: 8002, name: '王芳', position: '高级前端工程师', status: '待排期', statusKey: 'shortlisted', score: 90, stage: '项目案例深挖', updated: '昨天 17:40', tags: ['推荐', '沟通清晰'], color: '#1d8cf8', focus: '重点考察跨团队协作' },
  { id: 8003, name: '张敏', position: 'UI / UX 设计师', status: '待面试', statusKey: 'scheduled', score: 88, stage: 'AI 结构化预面', updated: '昨天 16:02', tags: ['作品集待看'], color: '#2667ff', focus: '补充用户研究案例' },
  { id: 8004, name: '陈晨', position: '高级前端工程师', status: '初筛通过', statusKey: 'screened', score: 85, stage: 'HR 初筛沟通', updated: '9月8日', tags: ['薪资待确认'], color: '#f59e0b', focus: '确认到岗时间和薪资预期' },
  { id: 8005, name: '赵磊', position: '产品经理', status: '已淘汰', statusKey: 'rejected', score: 82, stage: '已终止', updated: '9月7日', tags: ['已通知'], color: '#ef4444', focus: '不符合岗位硬性条件' }
])
const filtered = computed(() => candidates.value.filter(item => (!keyword.value || `${item.name}${item.position}${item.tags.join('')}`.includes(keyword.value)) && (status.value === '全部状态' || item.status === status.value)))
function notify(v){toast.value=v;setTimeout(()=>toast.value='',2000)}
function toggle(id){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
function importResume(){reserveApi({method:'POST',path:'/api/v1/enterprise/resumes/import',body:['files','positionId','deduplicate']},{files:[],positionId:1,deduplicate:true});notify('已预留企业简历批量导入接口')}
function batchTag(){if(!selected.value.length)return notify('请先选择候选人');reserveApi(api.candidates.batchTags,{candidateIds:selected.value,tagId:10,action:'add'});notify(`已为 ${selected.value.length} 位候选人加入标签`)}
function updateStatus(){if(!selected.value.length)return notify('请先选择候选人');reserveApi(api.candidates.status,{candidateIds:selected.value,status:'shortlisted',remark:'批量进入复核'});notify('状态更新已加入队列')}
</script>

