    <div class="candidate-layout"><section class="card list-card"><div class="toolbar"><label class="search-box"><Search :size="16"/><input v-model="keyword" placeholder="搜索姓名、岗位或标签"/></label><select v-model="status" class="select"><option>全部状态</option><option>面试中</option><option>待排期</option><option>待面试</option><option>初筛通过</option><option>已淘汰</option></select><button class="filter-btn"><SlidersHorizontal :size="15"/>筛选</button></div><div class="batch-bar"><span>已选 {{ selected.length }} 人</span><button class="btn sm" @click="batchTag"><Tags :size="14"/>批量加标签</button><button class="btn sm" @click="updateStatus"><Send :size="14"/>批量更新状态</button></div><div class="candidate-table"><div class="table-head"><span></span><span>候选人</span><span>匹配度</span><span>当前阶段</span><span>状态</span><span>更新时间</span><span>操作</span></div><article v-for="item in filtered" :key="item.id" class="table-row"><button class="check" :class="{on:selected.includes(item.id)}" @click="toggle(item.id)">✓</button><div class="person"><MiniAvatar :name="item.name" :size="34" :color="item.color"/><div><b>{{ item.name }}</b><small>{{ item.position }}</small><div class="tags"><span v-for="tag in item.tags" :key="tag">{{ tag }}</span></div></div></div><div class="score-cell"><strong>{{ item.score }}%</strong><i><u :style="{width:`${item.score}%`}"/></i></div><span class="stage-text">{{ item.stage }}</span><span class="pill" :class="item.statusKey === 'rejected' ? 'red' : item.statusKey === 'interviewing' ? 'purple' : item.statusKey === 'screened' ? 'orange' : 'green'">{{ item.status }}</span><time>{{ item.updated }}</time><div class="ops"><button @click="router.push(`/enterprise/candidates/${item.id}/process`)"><ArrowUpRight :size="13"/>流程</button><button @click="notify('简历预览接口已预留')"><FileText :size="13"/>简历</button></div></article></div></section><aside class="card insight-card"><div class="insight-title"><span><UserRoundCheck :size="17"/></span><div><h2>AI 复核摘要</h2><p>基于岗位画像和候选人简历</p></div></div><div class="summary-number"><strong>3</strong><span>高潜短名单</span><small>Top 20 粗排后由 LLM 深度分析</small></div><div class="insight-list"><div><b>待核实项</b><p>候选人个人贡献、薪资预期、到岗时间</p></div><div><b>匹配维度</b><p>技能覆盖 96% · 经验相关度 90% · 教育背景 88%</p></div><div><b>下一步</b><p>优先安排王芳的项目案例深挖阶段</p></div></div><button class="btn primary full" @click="router.push('/enterprise/candidates/8002/process')">查看重点候选人流程</button></aside></div><ToastMessage :message="toast"/></div>
</template>

